 // the timeout while processing, do not lower the number.
 export const VISIBILITY_TIMEOUT_S = 300;

+// How often a live worker extends the visibility deadline (seconds).
+// Must be shorter than VISIBILITY_TIMEOUT_S so a crashed worker's message
+// becomes visible again within one interval — addressing Q-58 without
+// triggering the duplicate-delivery bug from #418.
+export const HEARTBEAT_INTERVAL_S = 30;
+
+/**
+ * Starts a periodic heartbeat that calls `extend` every HEARTBEAT_INTERVAL_S
+ * seconds to keep the message invisible while the worker is alive.
+ * Call the returned stop function when processing is done (or on error).
+ *
+ * If the worker crashes the heartbeat stops, and the message becomes visible
+ * again after at most HEARTBEAT_INTERVAL_S seconds — not after the full
+ * VISIBILITY_TIMEOUT_S — so another worker can pick it up promptly (Q-58).
+ */
+export function startHeartbeat(extend: () => Promise<void>): () => void {
+  const timer = setInterval(() => {
+    extend().catch(() => {
+      // If the extend call fails the message will eventually reappear;
+      // swallow the error so a transient network hiccup does not crash
+      // the worker during an otherwise healthy processing run.
+    });
+  }, HEARTBEAT_INTERVAL_S * 1000);
+  return () => clearInterval(timer);
+}
+
 export async function consume(handler: (m: unknown) => Promise<void>) {
   // processing takes up to 240 s for large batches
 }

